#include <bits/stdc++.h>
using namespace std;


void solve(){
    int n;cin >> n;
    vector<int> a(n);
    for(auto &X : a)cin >> X;
    
    int MX = -1;
    int SMX =-1; 
    for(int i=0;i<n;i++){
        int fb=abs(a[i]-a[(i+1)%n]);
        if (fb>=MX){
            SMX=MX;
            MX=fb;
        }
        else if (fb>SMX){
            SMX=fb;
        }
    }
    cout << SMX << "\n";
}
int main() {
	// your code goes here
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int t; cin >> t;
    while(t--){
        solve();
    }
}
